UPDATE batches
             SET first_logged_at = first_logged_date + first_logged_time
             WHERE first_logged_date IS NOT NULL AND first_logged_time IS NOT NULL;

UPDATE batch_log_entries
             SET line_clearance_at = line_clearance_date + line_clearance_time
             WHERE line_clearance_date IS NOT NULL AND line_clearance_time IS NOT NULL;

UPDATE products SET created_by = 'default-user' WHERE created_by IS NULL;
UPDATE products SET created_at = NOW() WHERE created_at IS NULL;
UPDATE products SET last_updated_by = 'default-user' WHERE last_updated_by IS NULL;
UPDATE products SET last_updated_at = NOW() WHERE last_updated_at IS NULL;

